const strokeCache=new Map();
function strokeMasks(ch){if(strokeCache.has(ch))return strokeCache.get(ch);const data=glyphs[ch];if(!data)return null;const n=160,a=document.createElement('canvas');a.width=a.height=n;const z=a.getContext('2d');z.font=`140px "${cfg.font}"`;z.textAlign='center';z.textBaseline='middle';z.fillStyle='#ffffff';z.fillText(ch,80,83);const src=z.getImageData(0,0,n,n);const masks=data.medians.map(()=>new Uint8ClampedArray(n*n*4));const paths=data.medians.map(points=>points.map(([x,y])=>[x/1024*140+10,(900-y)/1024*140+10]));for(let y=0;y<n;y++)for(let x=0;x<n;x++){let off=(y*n+x)*4;if(src.data[off+3]<8)continue;let best=Infinity,idx=0;paths.forEach((pts,k)=>{for(let j=1;j<pts.length;j++){let[a,b]=pts[j-1],[c,d]=pts[j],dx=c-a,dy=d-b,t=clamp(((x-a)*dx+(y-b)*dy)/(dx*dx+dy*dy||1)),dist=(x-a-t*dx)**2+(y-b-t*dy)**2;if(dist<best){best=dist;idx=k}}});masks[idx][off]=masks[idx][off+1]=masks[idx][off+2]=255;masks[idx][off+3]=src.data[off+3]}const canvases=masks.map(bytes=>{let c=document.createElement('canvas');c.width=c.height=n;c.getContext('2d').putImageData(new ImageData(bytes,n,n),0,0);return c});strokeCache.set(ch,canvases);return canvases}
